/// low-byte ENUM encoding is also accepted for robustness. Out-of-range values
/// fall back to `Fill`.
pub fn align_from(raw: u32) -> Align {
    let f = f32::from_bits(raw);
    let idx = if f.is_finite() && f.fract() == 0.0 && (0.0..=3.0).contains(&f) {
        f as u8
    } else {
        (raw & 0xFF) as u8
