+            node_id: 9,
+            x: 0.0,
+            y: 0.0,
+            value: 0.0,
+            str_len: text.len() as u32,
+            str_: text.as_ptr() as *const c_char,
+        };
+        ring_event(&raw, user);
+        let events = ring.borrow_mut().drain_events();
+        assert_eq!(events.len(), 1);
+        match &events[0] {
