+        ]);
+        let mut slots2 = Vec::new();
+        slots2.extend_from_slice(&create.to_bytes());
+        let frame2 = pathland_core::Frame::from_parts(&slots2, &[], 0, slots2.len());
+        assert!(!frame_has_reset(&frame2), "non-reset frames must not reset");
