    QtAction::Send(event) => { runner.pump.send_input(&event); wake }
    QtAction::Scheme(s) => { runner.renderer.set_scheme(s); }
    QtAction::None => {}
}
```
For RingRunner, Send → DriverTransport::send_input on ring; Scheme → renderer.set_scheme; and wake on Send only.

