Now add the shared dispatch + frame_has_reset, and update both pump_once and the event handlers. Let me refactor run.rs. I'll add:

```rust
/// What to do with a Qt raw input.
enum QtAction {
    Send(Event),
    Scheme(Scheme),
    None,
}

/// Decode a `QtEvent` (C++ -> Rust) into an action. Control/pointer events are
/// encoded + written into the ring; a scheme change re-resolves tokens in the
/// renderer (no host wake).
fn decode_event(raw: &QtEvent) -> QtAction {
    match raw.kind {
        ev::POINTER_DOWN => QtAction::Send(Event::PointerDown { target: raw.node_id, x: raw.x, y: raw.y, secondary: false }),
        ev::POINTER_MOVE => QtAction::Send(Event::PointerMove { target: raw.node_id, x: raw.x, y: raw.y, hovering: false, leaving: false }),
        ev::POINTER_UP => QtAction::Send(Event::PointerUp { target: raw.node_id, x: raw.x, y: raw.y, secondary: false }),
        ev::VALUE_CHANGED => QtAction::Send(Event::ValueChanged { target: raw.node_id, value: raw.value }),
        ev::TEXT_CHANGED => {
            let slice = unsafe { std::slice::from_raw_parts(raw.str_ as *const u8, raw.str_len as usize) };
            QtAction::Send(Event::TextChanged { target: raw.node_id, value: String::from_utf8_lossy(slice).into_owned() })
        }
        ev::NAVIGATE_BACK => QtAction::Send(Event::Navigate { url: None }),
        ev::SCHEME_CHANGED => QtAction::Scheme(if raw.value >= 0.5 { Scheme::Dark } else { Scheme::Light }),
        _ => QtAction::None,
    }
}

/// Whether a frame carries `META::RESET` (clear all output).
fn frame_has_reset(frame: &pathland_core::Frame<'_>) -> bool {
    frame
        .opcodes()
        .any(|op| op.category() == category::META && op.command() == meta::RESET)
}
```

Then pump_once:
```rust
fn pump_once(runner: &mut Runner) {
    match runner.pump.next_frame() {
        Ok(Some(batch)) => {
            let frame = batch.frame();
            if frame_has_reset(frame) {
                runner.renderer.reset();
            } else {
                runner.renderer.apply_frame(frame);
            }
        }
        Ok(None) => {}
        Err(_) => {}
    }
}
```
Same for pump_once_ring.

