     /// Full pipeline: DSL -> engine -> frame -> shared decode -> delta diff ->
     /// FFI -> live QML scene. Asserts the real widgets in the offscreen scene.
     #[test]
     fn renderer_drives_live_qml_scene() {
         with_qt(|| {
