// Create a StackView (the nav container), transitions disabled so the
// depth-reconcile is deterministic (and offscreen-testable).
QQuickItem *createNavStack(uint32_t slotId, QQuickItem *previous) {
    QQuickItem *stack = createComponent(
        g.engine, previous ? previous->parentItem() : g.root,
        "import QtQuick 2.15\nimport QtQuick.Controls 2.15\nStackView { objectName: \"nav%1\" }"
