    QQmlComponent comp(g.engine);
    comp.setData(QByteArray("import QtQuick 2.15\nComponent {}"), QUrl());
    if (QObject *c = comp.create()) {
        stack->setProperty("transitionDelegate", QVariant::fromValue(c));
