void reconcileNav(uint32_t slotId) {
    auto sit = g.nav_stacks.find(slotId);
    if (sit == g.nav_stacks.end()) return;
    QQuickItem *stack = sit->second;
    const QString route = g.nav_route.count(slotId) ? g.nav_route[slotId] : QString();
    const uint32_t depth = std::max(g.nav_depth[slotId], 1u);
    const bool custom = g.nav_custom_chrome.count(slotId);

