    if (pages.empty()) {
        // Root page.
        QQuickItem *page = custom ? dest : navPageWrapper(slotId, /*isRoot=*/true);
        if (custom) {
            if (dest) dest->setParentItem(nullptr); // ensure not reparented to contentItem
        } else if (dest) {
            placeDestination(dest, page->findChild<QQuickItem *>("content"));
        }
        QMetaObject::invokeMethod(stack, "push", Q_ARG(QVariant, QVariant::fromValue(page)));
        pages.push_back(page);
        tags.push_back(route);
        return;
    }

    // Depth decision (mirrors the GTK renderer's nav_action).
    QQuickItem *top = pages.back();
    const QString topTag = tags.back();
    if (topTag == route) {
        // Refresh in place.
        if (!custom && dest) placeDestination(dest, top->findChild<QQuickItem *>("content"));
    } else if (pages.size() < depth) {
        // Push a new page.
        QQuickItem *page = custom ? dest : navPageWrapper(slotId, /*isRoot=*/false);
        if (custom) {
            if (dest) dest->setParentItem(nullptr);
        } else if (dest) {
            placeDestination(dest, page->findChild<QQuickItem *>("content"));
        }
        QMetaObject::invokeMethod(stack, "push", Q_ARG(QVariant, QVariant::fromValue(page)));
        pages.push_back(page);
        tags.push_back(route);
    } else {
