                dest->setParentItem(nullptr);
                QMetaObject::invokeMethod(stack, "replace", Q_ARG(QVariant, QVariant::fromValue(dest)));
                pages.back() = dest;
            }
        } else if (dest) {
            placeDestination(dest, top->findChild<QQuickItem *>("content"));
        }
        tags.back() = route;
    }
}
