// A StackView with transitions disabled: the renderer reconciles by depth, and
// an empty transitionDelegate keeps push/pop immediate + offscreen-deterministic.
QQuickItem *createNavStack(QQuickItem *parent) {
    return createComponent(
        g.engine, parent,
        "import QtQuick 2.15\nimport QtQuick.Controls 2.15\n"
        "StackView { transitionDelegate: Component {} }");
}

// Promote a slot's Column/Row to a StackView (first non-empty ROUTE). Children
// are inserted after props, so the slot has none yet — safe to swap.
void promoteNavSlot(uint32_t slotId) {
    auto it = g.widgets.find(slotId);
    if (it == g.widgets.end()) {
        return;
    }
    QQuickItem *old = it->second;
    QQuickItem *stack = createNavStack(old->parentItem());
    if (!stack) {
        return;
    }
    QObject *anchors = stack->property("anchors").value<QObject *>();
    if (anchors && old->parentItem()) {
        anchors->setProperty("fill", QVariant::fromValue(old->parentItem()));
    }
    g.widgets[slotId] = stack;
    g.nav_slots.insert(slotId);
    g.nav_stacks[slotId] = stack;
    old->deleteLater();
}

// PlatformDefault chrome: a page wrapper with a header back button (visible
// except on the root page) over a content placeholder. The back button reports
// a native back request directly; the app pops its own back-stack and re-emits.
QQuickItem *navPageWrapper(bool isRoot) {
    return createComponent(
