     #[allow(dead_code)]
     pub fn pathland_qt_layer_widget_text(id: u32, out: *mut c_char, cap: u32) -> u32;
     #[allow(dead_code)]
     pub fn pathland_qt_layer_widget_prop_text(
         id: u32,
