 #include <QtCore/QVariant>

 #include <algorithm>
 #include <cmath>
 #include <cstring>
 #include <unordered_map>
 #include <unordered_set>
 #include <vector>

 #include "bridge.h"

 // Component type IDs (spec/PRIMITIVES.md).
 enum {
     PL_COMP_TEXT = 0x01,
     PL_COMP_IMAGE = 0x02,
     PL_COMP_COLOR = 0x03,
